["custom"] = "local e = aura_env \n\nif not e.btn then \n    local region = WeakAuras.GetRegion(e.id) \n    \n    -- 将父级框架改为 UIParent 避免安全模板污染\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", UIParent, \"SecureActionButtonTemplate\") \n    \n    -- 注册所有点击事件（AnyDown 包含左、右、中及侧键）\n    e.btn:RegisterForClicks(\"AnyDown\")\n    \n    -- 1. 左键：魔法晶水\n    e.btn:SetAttribute(\"type1\", \"item\")\n    e.btn:SetAttribute(\"item1\", \"魔法晶水\")\n    \n    -- 2. 右键：可口的魔法点心\n    e.btn:SetAttribute(\"type2\", \"item\")\n    e.btn:SetAttribute(\"item2\", \"可口的魔法点心\")\n    \n    -- 3. 中键：奥特兰克魔法点心\n    e.btn:SetAttribute(\"type3\", \"item\")\n    e.btn:SetAttribute(\"item3\", \"奥特兰克魔法点心\")\n    \n    e.btn:SetAllPoints(region) \n    e.btn:SetFrameStrata(\"TOOLTIP\")\n    e.btn:SetFrameLevel(9999)\nend \n\nlocal btn = e.btn \nbtn:Show()",
["do_custom"] = true,
},
},
