["preferToUpdate"] = true,
["customText"] = "function(t)\n    return[[|cffff78ab如何复制|r：鼠标放在想复制的文字上，打|cffff78ab/copy|r。需要加载|cffff78abcopy anything|r插件。]]\nend",
