["custom"] = "local e = aura_env\nif not InCombatLockdown() then\n    if not _G[e.id..\"Button\"] then\n        local region = e.region or WeakAuras.GetRegion(e.id)\n        if region then\n            local btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\")\n            btn:RegisterForClicks(\"AnyUp\", \"AnyDown\")\n            btn:SetAttribute(\"type1\", \"macro\")\n            btn:SetAttribute(\"type2\", \"macro\")\n            btn:SetAttribute(\"macrotext1\", \"/use 法力翡翠\")\n            btn:SetAttribute(\"macrotext2\", \"/cast 制造魔法翡翠\")\n            btn:SetScript(\"OnEnter\", function(self)\n                    GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n                    GameTooltip:SetText(\"|r\"..e.id..\"\\n\", 0, 1, 0, 1, 1)\n            end)\n            btn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\n        end\n    end\n    local btn = _G[e.id..\"Button\"]\n    if btn then\n        if e.region then\n            btn:ClearAllPoints()\n            btn:SetAllPoints(e.region)\n        end\n        btn:Show()\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "local e = aura_env\nif not InCombatLockdown() then\n    local btn = _G[e.id..\"Button\"]\n    if btn then\n        btn:Hide()\n    end\nend",
["do_custom"] = true,
},
