["parent"] = "【Luxthos】小号经验条（汉化与修改：露露緹婭@Bilibili）",
["adjustedMin"] = "",
["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["duration"] = "1",
