["custom"] = "aura_env.MSC = {[\"RALT\"] = false,[\"LALT\"] = false,[\"LCTRL\"] = false,[\"LSHIFT\"] = false,[\"RSHIFT\"] = false,[\"RCTRL\"] = false}\nC_ChatInfo.RegisterAddonMessagePrefix(\"CRAM_CLEAR\")",
